-- Release 2026-10-18 · bước 2/3: 8 bài viết
--
-- Sinh ra TỪ DATABASE LOCAL (không phải từ file markdown), nên thứ lên server
-- đúng bằng thứ đã duyệt ở local, kể cả các sửa trong console.
--
-- Ba điều file này làm theo nguyên tắc:
--
-- 1. Khoá ngoại nối bằng KHOÁ TỰ NHIÊN, không bằng uuid local: tác giả tra
--    theo email, danh mục tra theo slug. Trên server chúng mang id khác.
-- 2. Bản ghi GIỮ NGUYÊN id của chính nó. Các dòng trong `files` trỏ vào id đó,
--    và đường dẫn ảnh trên đĩa cũng chứa id đó — nên id phải đi theo. Nhờ vậy
--    chạy lại lần hai là cập nhật tại chỗ, không nhân đôi.
-- 3. THIẾU PHỤ THUỘC THÌ DỪNG. Khối DO ở dưới báo lỗi đọc được, thay vì để
--    INSERT chết với thông báo khoá ngoại chỉ nêu tên cột.
--
-- Có cả published_docs nên trang công khai hiện bài ngay, không phải vào
-- console bấm xuất bản lại 8 lần.
--
--   psql -d <db> -v ON_ERROR_STOP=1 -f 02-articles.sql

BEGIN;

DO $guard$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM users WHERE email = 'trungld@zakutek.com') THEN
    RAISE EXCEPTION 'Thieu tai khoan tac gia trungld@zakutek.com — tao user truoc roi chay lai';
  END IF;
END
$guard$;

