INSERT INTO published_docs (entity, locale, slug, entity_id, is_current, search_text, body, published_at, written_at)
VALUES ('article', 'vi', 'bao-mat-toi-thieu-cho-website-doanh-nghiep', '3493cf5d-80c9-5187-bc75-86ba0d724cae', true, 'Bảo mật tối thiểu cho một website doanh nghiệp: bảy thứ, theo thứ tự Bảy bước kiểm tra ban đầu cho website doanh nghiệp, từ băm mật khẩu tới nhật ký truy cập bí mật; không thay thế kiểm toán bảo mật đầy đủ.', E'{"seo": {"title": "Bảo mật website doanh nghiệp: 7 việc tối thiểu theo thứ tự ưu tiên", "noindex": false, "keywords": "bảo mật website, giới hạn tần suất, reCAPTCHA, mã hoá mật khẩu, argon2, HTTPS", "nofollow": false, "og_title": "", "description": "Bảy bước rà soát mật khẩu, giới hạn tần suất, lỗi xác thực, bí mật trong backup, dữ liệu công khai và nhật ký truy cập.", "canonical_url": "", "og_description": ""}, "slug": "bao-mat-toi-thieu-cho-website-doanh-nghiep", "title": "Bảo mật tối thiểu cho một website doanh nghiệp: bảy thứ, theo thứ tự", "excerpt": "Bảy bước kiểm tra ban đầu cho website doanh nghiệp, từ băm mật khẩu tới nhật ký truy cập bí mật; không thay thế kiểm toán bảo mật đầy đủ.", "og_path": null, "tag_ids": [], "body_html": "<p>Bài này không liệt kê 50 việc. Nó liệt kê bảy, theo một thứ tự khởi đầu thực tế. Mỗi việc có bước tự kiểm tra ban đầu; đây không phải bộ kiểm toán bảo mật đầy đủ. Cần thêm cập nhật phần mềm, MFA, sao lưu và thử khôi phục, HTTPS, quản lý phiên và theo dõi sự cố.</p><p>Mọi ví dụ đều lấy từ hệ thống của chúng tôi, kể cả những chỗ chúng tôi làm sai trước khi làm đúng.</p><h2>1. Mật khẩu: argon2id, không phải MD5, không phải SHA-256</h2><p>Nếu cơ sở dữ liệu rò rỉ, <strong>thuật toán băm và cách cấu hình</strong> ảnh hưởng lớn đến khả năng kẻ tấn công dò ra mật khẩu và thử lại ở những nơi khác.</p><ul><li><p><code>MD5</code>, <code>SHA-1</code>, <code>SHA-256</code> trần — hỏng. Chúng được thiết kế để <strong>nhanh</strong>, mà nhanh chính là thứ kẻ tấn công cần</p></li><li><p><code>bcrypt</code> — chấp nhận được</p></li><li><p><code>argon2id</code> — lựa chọn được OWASP khuyến nghị cho hệ thống mới. Tốn bộ nhớ, nên dò bằng dàn GPU rất đắt</p></li></ul><p><strong>Tự kiểm tra:</strong> mở bảng người dùng, nhìn một ô mật khẩu. Tiền tố <code>$argon2id$</code> hay <code>$2a$</code>/<code>$2b$</code> giúp nhận diện thuật toán, nhưng chưa chứng minh tham số, salt và cách triển khai đủ an toàn. Nếu nó là một chuỗi hex 32 hay 64 ký tự, bạn có việc phải làm ngay hôm nay.</p><h2>2. Giới hạn tần suất ở mọi cửa công khai</h2><p>Mọi endpoint không cần đăng nhập đều là một cửa. Form liên hệ, đăng ký nhận tin, khung chat, đăng nhập — mỗi cái đều có thể bị gọi mười nghìn lần.</p><p>Chỗ nguy hiểm nhất là <strong>cửa nào tiêu tiền</strong>. Khung chat của chúng tôi gọi tới nhà cung cấp AI, nghĩa là mỗi tin nhắn là một khoản chi. Một cửa công khai không giới hạn, nối thẳng vào một dịch vụ tính tiền theo lượt, là cách mất tiền nhanh nhất mà không ai nhận ra cho tới khi nhận hoá đơn.</p><p>Khi chúng tôi kiểm tra hệ thống, nginx <strong>không có một dòng giới hạn nào</strong>. Sau khi thêm:</p><ul><li><p><strong>Mở trang bình thường, tải hết tài sản</strong> — Kết quả: <strong>0 lần bị chặn</strong></p></li><li><p><strong>150 yêu cầu tuần tự</strong> — Kết quả: 17 lần chặn</p></li><li><p><strong>300 yêu cầu song song</strong> — Kết quả: <strong>225 lần chặn</strong></p></li></ul><p>Phép thử đầu quan trọng ngang hai phép sau. Một giới hạn chặn cả khách thật thì sẽ bị gỡ sau một tuần, và khi đó bạn không có gì cả.</p><p><strong>Tự kiểm tra:</strong> thử theo ngưỡng của endpoint công khai trên môi trường được phép. Không thấy <code>429</code> chưa chứng minh thiếu giới hạn: còn phụ thuộc ngưỡng, cửa sổ thời gian, burst và khoá định danh. Chỉ thử trên staging hoặc hệ thống được phép, theo ngưỡng đã cấu hình; tránh tạo tải lên dịch vụ thật ngoài kế hoạch.</p><h2>3. Trả về 429, đừng trả 503</h2><p>Chi tiết nhỏ nhưng đáng nói. <code>503</code> nói &#34;máy chủ hỏng&#34;. <code>429</code> nói đúng sự thật: &#34;bạn gọi quá nhanh&#34;.</p><p>Khác biệt không chỉ là lịch sự. Công cụ chặn tự động phải được cấu hình đọc đúng mã và mẫu log; không có quy tắc chung rằng chúng luôn hiểu 429 và không hiểu 503.</p><h2>4. Fail-closed, đừng fail-open</h2><p>Nguyên tắc quan trọng nhất trong bài này.</p><p>Khi một lớp bảo vệ không chạy được, nó phải <strong>từ chối</strong>, không được <strong>cho qua</strong>.</p><p>Ví dụ thật trong hệ thống của chúng tôi: module kiểm tra reCAPTCHA. Khi không gọi được tới máy chủ của Google, nó <strong>không</strong> coi đó là hợp lệ:</p><pre><code>// Google unreachable is NOT a pass.\\nreturn fmt.Errorf(&#34;recaptcha unreachable: %w&#34;, err)</code></pre><p>Hệ quả: khi Google gặp sự cố, form liên hệ của chúng tôi báo lỗi. Khó chịu cho khách — nhưng đúng. Lựa chọn còn lại là mở toang cánh cửa mỗi lần một dịch vụ bên thứ ba trục trặc, và kẻ tấn công thì rất giỏi tạo ra trục trặc.</p><p>Thiếu khoá là lỗi cấu hình, không phải lý do âm thầm bỏ kiểm tra. Giao diện quản trị nên từ chối bật chế độ bắt buộc khi chưa đủ khoá và báo rõ trạng thái. Nếu runtime đang yêu cầu CAPTCHA mà không xác minh được, hãy từ chối thao tác hoặc chuyển sang kênh hỗ trợ đã thiết kế trước, không giả vờ đã xác thực. Chính sách dự phòng cần được chọn theo rủi ro của từng luồng.</p><h2>5. Bí mật không bao giờ nằm trong mã nguồn</h2><p>Nghe hiển nhiên, nhưng chỗ rò rỉ thường nằm ở nơi không ai nhìn: <strong>bản sao lưu cơ sở dữ liệu</strong>.</p><p>Khi chúng tôi tạo bản dump để đưa lên máy chủ, lần quét đầu tiên &#34;sạch&#34;. Lần quét thứ hai, kỹ hơn, tìm thấy khoá bí mật reCAPTCHA — nó nằm trong một cột tên <code>value_encrypted</code> mà lần quét đầu không nhìn tới.</p><p>Rà lại toàn bộ, có <strong>bốn cột</strong> chứa bí mật trong lược đồ:</p><pre><code>ai_providers.api_key              khoá API nhà cung cấp AI\\npush_keys.private_key             khoá riêng thông báo đẩy\\nsystem_settings.value_encrypted   secret reCAPTCHA\\ntwo_factor_secrets.secret         mã 2FA từng người</code></pre><p><strong>Tự kiểm tra:</strong> mở bản sao lưu mới nhất bằng trình soạn thảo văn bản, tìm <code>sk-</code>, <code>api_key</code>, <code>secret</code>, <code>BEGIN PRIVATE KEY</code>. Đây chỉ là bước sàng lọc: bí mật có thể ở cột text, JSON, nhị phân hoặc được mã hoá. Rà lược đồ và cấu hình, giới hạn quyền đọc backup, mã hoá và đặt thời hạn lưu; nếu từng lộ thì phải thu hồi hoặc xoay khoá.</p><h2>6. Mỗi loại dữ liệu một mức quyền</h2><p>Dễ nhất là cho tất cả mọi người thấy tất cả mọi thứ. Nó cũng là thứ khiến một tài khoản bị chiếm thành một sự cố toàn hệ thống.</p><p>Một ví dụ cụ thể: trang web của chúng tôi hiển thị đội ngũ. Trước đây nó trả về tên thật và email của từng người. Mỗi email đó cũng là một tài khoản đăng nhập — nghĩa là trang giới thiệu đang <strong>làm lộ định danh có thể dùng để dò tài khoản và phishing</strong> cho bất kỳ ai xem mã nguồn trang.</p><p>Cách sửa không phải là xoá trường ở từng chỗ hiển thị. Là làm <strong>một điểm nghẽn duy nhất</strong>: mọi đường đọc công khai đều đi qua một hàm bóc bỏ tên thật và email. Cần kiểm tra mọi endpoint mới cũng đi qua lớp này; mô tả kiến trúc chưa tự chứng minh không tồn tại đường vòng.</p><p><strong>Tự kiểm tra:</strong> mở trang công khai, xem mã nguồn hoặc gọi API, tìm email và tên thật. Nếu thấy, hỏi: thông tin này có cần cho khách không?</p><h2>7. Đọc một bí mật cũng là một hành động cần ghi lại</h2><p>Mục này ít hệ thống làm, và nó rẻ.</p><p>Tạo hay sửa một cấu hình thì bản thân cấu hình đã là dấu vết. Nhưng <strong>đọc</strong> một khoá API thì không để lại gì cả. Nếu sau này khoá bị lạm dụng, câu hỏi &#34;ai đã xem nó&#34; không có câu trả lời.</p><p>Chúng tôi làm chức năng xem lại khoá API đã lưu với ba lớp, và cần cả ba:</p><ol><li><p><strong>Quyền</strong> — phải là quản trị viên</p></li><li><p><strong>Nhập lại mật khẩu</strong> — giúp giảm nguy cơ từ một phiên bỏ quên; không chứng minh tuyệt đối danh tính. Với thao tác nhạy cảm, cân nhắc MFA hoặc xác thực lại phù hợp. Cookie phiên chỉ chứng minh họ <strong>đã</strong> ở đó lúc đăng nhập</p></li><li><p><strong>Giới hạn tần suất</strong> — để cửa này không thành chỗ dò mật khẩu</p></li></ol><p>Và mỗi lần xem đều ghi một dòng nhật ký: ai, lúc nào, định danh khoá nào — không ghi giá trị bí mật. Ưu tiên che khoá và cho xoay khoá thay vì cho đọc lại.</p><h2>Bảng tự chấm</h2><ol><li><p><strong>Băm mật khẩu</strong> — Kiểm tra trong 5 phút: Nhìn một ô <code>password_hash</code>, có <code>$argon2id$</code> không</p></li><li><p><strong>Giới hạn tần suất</strong> — Kiểm tra trong 5 phút: Thử theo ngưỡng cấu hình trên môi trường được phép</p></li><li><p><strong>Mã lỗi đúng</strong> — Kiểm tra trong 5 phút: Khi bị chặn trả <code>429</code> hay <code>503</code></p></li><li><p><strong>Fail-closed</strong> — Kiểm tra trong 5 phút: Tắt mạng tới dịch vụ xác thực — form cho qua hay chặn</p></li><li><p><strong>Bí mật trong sao lưu</strong> — Kiểm tra trong 5 phút: Quét bản dump mới nhất, liệt kê cột nhị phân</p></li><li><p><strong>Dữ liệu công khai</strong> — Kiểm tra trong 5 phút: Xem mã nguồn trang, tìm email nội bộ</p></li><li><p><strong>Nhật ký đọc bí mật</strong> — Kiểm tra trong 5 phút: Có dòng nào ghi lại việc xem khoá không</p></li></ol><p>Nếu bạn trượt mục 1, hãy sửa nó trước mọi thứ khác. Nếu trượt mục 4, hãy đọc lại toàn bộ chỗ xử lý lỗi — một hệ thống fail-open thường fail-open ở nhiều nơi cùng lúc, vì đó là thói quen chứ không phải sơ suất.</p><hr><p><em>Các tình huống và số lượt chặn được giữ từ bản thảo Zukatek tháng 10/2026; chưa có log gốc để kiểm chứng độc lập.</em></p><p>Nguồn đối chiếu: <a href=\\"https://cheatsheetseries.owasp.org/cheatsheets/Password_Storage_Cheat_Sheet.html\\" rel=\\"nofollow\\">OWASP — Password Storage</a>.</p><p><em>Ảnh bìa là minh hoạ tạo bằng AI, không phải ảnh chụp hệ thống thật.</em></p>", "category_id": "527817a9-ade5-46d4-b64d-37d4bff2c875", "published_at": "2026-10-18T12:56:57.964814+07:00", "featured_path": "cms/articles/3493cf5d-80c9-5187-bc75-86ba0d724cae/featured-e94b24e1-70cf-5f04-b106-546e8c26e0cb.webp"}', '2026-10-18 12:56:57.96539+07', '2026-10-18 12:56:57.974786+07')
