INSERT INTO published_docs (entity, locale, slug, entity_id, is_current, search_text, body, published_at, written_at)
VALUES ('article', 'vi', 'chatbot-ai-khong-bia-dat', '32e26f10-59c0-561b-afb8-fb840106e5d8', true, 'Giảm chatbot AI bịa thông tin: kiểm soát bằng kiến trúc Trợ lý của chúng tôi từng bịa ra sáu nhân viên với những cái tên không có thật, trong khi đội chỉ có bốn người. Cách sửa không phải là dặn nó kỹ hơn.', E'{"seo": {"title": "Giảm thông tin bịa trong chatbot AI doanh nghiệp", "noindex": false, "keywords": "chatbot AI, ảo giác AI, hallucination, trợ lý ảo doanh nghiệp, RAG", "nofollow": false, "og_title": "", "description": "Vì sao chatbot bịa thông tin, và vì sao viết thêm lời dặn trong prompt không giải quyết được. Công cụ tra cứu, kiểm tra đầu ra và giới hạn của từng lớp bảo vệ.", "canonical_url": "", "og_description": ""}, "slug": "chatbot-ai-khong-bia-dat", "title": "Giảm chatbot AI bịa thông tin: kiểm soát bằng kiến trúc", "excerpt": "Trợ lý của chúng tôi từng bịa ra sáu nhân viên với những cái tên không có thật, trong khi đội chỉ có bốn người. Cách sửa không phải là dặn nó kỹ hơn.", "og_path": null, "tag_ids": [], "body_html": "<p>Lần đầu bật trợ lý AI cho website, chúng tôi hỏi nó một câu đơn giản: <em>&#34;Đội ngũ gồm những ai?&#34;</em></p><p>Nó trả lời rành mạch, liệt kê <strong>sáu người</strong> với tên, chức danh và mô tả công việc. Đọc rất thuyết phục.</p><p>Đội có bốn người. Không ai trong sáu cái tên đó có thật.</p><h2>Vì sao viết thêm lời dặn không giải quyết được</h2><p>Phản xạ đầu tiên của ai cũng giống nhau: thêm một dòng vào lời nhắc hệ thống. <em>&#34;Tuyệt đối không được bịa tên người.&#34;</em></p><p>Nó có tác dụng. Một phần. Trong phần lớn trường hợp. Và đó chính là vấn đề.</p><p>Một lời dặn trong prompt là <strong>một đề nghị gửi cho một hệ thống xác suất</strong>. Nó làm giảm khả năng xảy ra, không triệt tiêu. Mỗi lần người dùng hỏi theo một cách hơi khác, bạn lại đánh cược một lần nữa — và bạn không biết tỷ lệ thua là bao nhiêu.</p><p>Chỗ này có một ranh giới rất đáng nhớ:</p><blockquote><p><strong>Những gì mô hình không có trong ngữ cảnh thì nó không thể trích chính xác. Nhưng những gì nó không có, nó hoàn toàn có thể bịa.</strong></p></blockquote><p>Nên câu hỏi đúng không phải <em>&#34;làm sao dặn cho nó nghe lời&#34;</em>, mà <em>&#34;làm sao để câu trả lời sai trở thành bất khả thi về mặt cấu trúc&#34;</em>.</p><h2>Ba mức kiểm soát, từ yếu tới mạnh</h2><h3>Mức 1 — Lời dặn (yếu nhất)</h3><pre><code>Không được bịa tên người, số lượng thành viên hay vai trò.</code></pre><p>Đây là thứ chúng tôi vẫn giữ, nhưng <strong>chỉ như lớp cuối cùng</strong>. Trong mã nguồn, ngay cạnh dòng này, chúng tôi ghi một chú thích thẳng thắn: đây là chỗ duy nhất mà văn bản đang làm việc thật thay vì mô tả việc đã được kiến trúc bảo đảm — và cần biết rằng nó yếu hơn.</p><p>Ghi rõ chỗ yếu là một phần của việc làm cho nó an toàn. Thứ nguy hiểm là một lớp bảo vệ mà ai cũng tưởng chắc chắn.</p><h3>Mức 2 — Giảm dữ liệu nhạy cảm trong ngữ cảnh</h3><p>Quy tắc giá: <em>&#34;Không nói về giá, gói cước, chiết khấu.&#34;</em></p><p>Không đưa bảng giá nội bộ vào ngữ cảnh giúp giảm nguy cơ lộ dữ liệu đó. Nhưng mô hình vẫn có thể tự tạo một mức giá nghe hợp lý. <strong>Giảm dữ liệu nhạy cảm không đồng nghĩa ngăn bịa.</strong> Nếu sản phẩm không được phép báo giá, ứng dụng cần chặn ý định báo giá hoặc trả một mẫu cố định đã duyệt. Vẫn phải kiểm tra đầu ra, quyền truy cập công cụ và dữ liệu được truy xuất.</p><h3>Mức 3 — Tra cứu có kiểm tra ở phía ứng dụng</h3><p>Với dữ liệu mà trợ lý <strong>cần</strong> trả lời — danh sách sản phẩm, danh sách nhân sự — không thể không đưa vào. Giải pháp là không đưa sẵn, mà bắt nó <strong>đi hỏi</strong>:</p><pre><code>Mọi thông tin về sản phẩm, đội ngũ, con người phải lấy từ kết quả công cụ.\\nKhông có trong công cụ thì nói là chưa có thông tin.\\nDùng list_members; công cụ trả về bao nhiêu người thì đúng bấy nhiêu.</code></pre><p>Công cụ cung cấp đường tra cứu dữ liệu đã được duyệt; bản thân dữ liệu cũng cần được cập nhật và kiểm tra quyền truy cập.</p><p>Tuy nhiên, chỉ khai báo công cụ vẫn chưa bảo đảm mô hình sẽ dùng nó. Công cụ là nguồn duy nhất, nhưng <em>không có gì ngăn mô hình trả lời từ trí nhớ của nó thay vì gọi công cụ</em>. Đó đúng là chuyện đã xảy ra với sáu cái tên bịa.</p><p>Biện pháp mạnh hơn là ứng dụng bắt buộc tra cứu cho loại câu hỏi này, kiểm tra ID và số lượng trong câu trả lời, rồi từ chối hoặc chuyển người thật khi thiếu bằng chứng. Với danh sách nhân sự, có thể hiển thị trực tiếp bằng mẫu từ dữ liệu đã duyệt, không cho mô hình tự viết lại tên. Ba lớp này giải quyết các rủi ro khác nhau, không phải một thang bảo đảm tuyệt đối.</p><h2>Những quyết định nhỏ hơn nhưng quan trọng</h2><h3>Khung chat hẹp thì đừng cho vẽ bảng</h3><p>Trợ lý của chúng tôi bị cấm dùng bảng Markdown. Không phải vì bảng xấu, mà vì khung chat rộng khoảng 360 điểm ảnh — bảng nhiều cột thường khó đọc nếu không có bố cục thích ứng. Thay vì dạy giao diện vẽ bảng cho khéo, chúng tôi bảo trợ lý đừng dùng bảng.</p><p>Khi một thứ không thể hiển thị tốt, cách rẻ nhất là đừng tạo ra nó.</p><h3>Định dạng phải hiển thị, nhưng đừng bao giờ thành HTML</h3><p>Mô hình trả về <code>đậm</code> kiểu Markdown. Nếu để nguyên, người dùng thấy dấu sao. Một số cách render Markdown sinh <strong>chuỗi HTML</strong> và chèn bằng <code>dangerouslySetInnerHTML</code>; những thư viện khác render thành phần tử giao diện. Không phải mọi thư viện Markdown đều cần chèn HTML thô.</p><p>Và đây là chỗ nguy hiểm: <strong>đầu ra của mô hình bị khách lạ nắn được</strong>. Bảo trợ lý nhắc lại một đoạn, nó nhắc lại. Nếu đoạn đó là mã độc và bạn biến nó thành HTML, bạn vừa tạo ra một lỗ hổng tấn công lưu trữ.</p><p>Chúng tôi tự viết một thành phần nhỏ, chỉ hiểu <code>đậm</code>, <code>nghiêng</code>, `<code> </code>mã<code> </code>` và dòng tiêu đề, và <strong>trả về phần tử giao diện chứ không trả về chuỗi</strong>. Không có điểm nào trong toàn bộ đường đi mà một chuỗi bị diễn giải thành HTML — cách này loại bỏ đường chèn HTML thô trong thành phần đó. Vẫn phải kiểm tra giao thức URL, liên kết và các thành phần mở rộng; không thể suy ra toàn bộ ứng dụng miễn nhiễm XSS.</p><h3>Ngôn ngữ trả lời phải theo người đọc</h3><p>Site có hai ngôn ngữ. Ban đầu lời nhắc cứng tiếng Việt, nên khách đọc bản tiếng Anh vẫn nhận câu trả lời tiếng Việt.</p><p>Cách sửa đáng nói ở chỗ chúng tôi <strong>không dịch toàn bộ lời nhắc</strong>. Giữ bộ quy tắc bằng một ngôn ngữ (nếu nhân đôi, hai bản sẽ lệch nhau và những quy tắc quan trọng nhất là thứ lệch đầu tiên), chỉ thêm một khối ngôn ngữ đặt lên trên:</p><pre><code>RESPONSE LANGUAGE — security and access rules still apply\\n- The brief that follows is written in Vietnamese. Do not copy its language;\\n  follow its rules and answer in English.\\n- Exception: if the visitor asks for another language, use that one.</code></pre><p>Và ngoại lệ cuối cùng là cố ý: khách viết &#34;trả lời bằng tiếng Anh&#34; trong trang tiếng Việt thì đang yêu cầu tiếng Anh. Từ chối điều đó là máy móc.</p><h2>Danh sách kiểm tra trước khi bật chatbot</h2><ol><li><p><strong>Liệt kê mọi thứ trợ lý không được nói</strong> — giá, cam kết tiến độ, tư vấn pháp lý</p></li><li><p>Với mỗi thứ, hỏi: <em>dữ liệu đó có nằm trong ngữ cảnh không?</em> Nếu có, <strong>bỏ ra</strong></p></li><li><p>Với dữ liệu buộc phải có, đưa qua <strong>công cụ tra cứu</strong>, đừng đưa sẵn</p></li><li><p>Bắt buộc tra cứu khi cần; kiểm tra ID, số lượng và quyền ở phía ứng dụng</p></li><li><p>Render an toàn, không chèn HTML thô chưa xử lý; kiểm tra cả URL liên kết</p></li><li><p>Thử hỏi đúng những câu bạn sợ nhất, bằng vài cách diễn đạt khác nhau</p></li></ol><p>Bước 6 là bước hay bị bỏ. Chúng tôi chỉ phát hiện ra sáu cái tên bịa vì có người hỏi một câu rất bình thường.</p><hr><p><em>Tình huống sáu nhân viên được thuật lại từ bản thảo Zukatek tháng 10/2026; nhật ký gốc chưa có trong thư mục để kiểm chứng độc lập.</em></p><p>Nguồn đối chiếu: <a href=\\"https://genai.owasp.org/llmrisk/llm092025-misinformation/\\" rel=\\"nofollow\\">OWASP — LLM Misinformation</a>.</p><p><em>Ảnh bìa là minh hoạ tạo bằng AI, không phải ảnh chụp hệ thống thật.</em></p>", "category_id": "527817a9-ade5-46d4-b64d-37d4bff2c875", "published_at": "2026-10-18T12:57:06.374158+07:00", "featured_path": "cms/articles/32e26f10-59c0-561b-afb8-fb840106e5d8/featured-dcbf3098-b10a-5d49-9b21-89bbdd84a98b.webp"}', '2026-10-18 12:57:06.374748+07', '2026-10-18 12:57:06.387092+07')
