INSERT INTO published_docs (entity, locale, slug, entity_id, is_current, search_text, body, published_at, written_at)
VALUES ('article', 'vi', 'thong-bao-cho-doi-web-push-email-zalo', '5eb8c4fb-5989-51c1-b18a-635d80045a77', true, 'Báo tin cho đội khi có khách: Web Push, email hay Zalo? Chọn kênh báo tin nội bộ theo thiết bị, quyền nhận và cách xử lý khi tin không tới. Web Push và email bổ trợ nhau; tích hợp Zalo cần xác nhận chính sách trước.', E'{"seo": {"title": "Thông báo cho đội khi có khách liên hệ: Web Push, email hay Zalo ZNS", "noindex": false, "keywords": "Web Push, thông báo đẩy, Zalo ZNS, ZBS Template, thông báo nội bộ", "nofollow": false, "og_title": "", "description": "Cách chọn Web Push, email và Zalo để báo khách liên hệ: giới hạn giao nhận, quyền truy cập, chống dội và kênh dự phòng.", "canonical_url": "", "og_description": ""}, "slug": "thong-bao-cho-doi-web-push-email-zalo", "title": "Báo tin cho đội khi có khách: Web Push, email hay Zalo?", "excerpt": "Chọn kênh báo tin nội bộ theo thiết bị, quyền nhận và cách xử lý khi tin không tới. Web Push và email bổ trợ nhau; tích hợp Zalo cần xác nhận chính sách trước.", "og_path": null, "tag_ids": [], "body_html": "<p>Bài toán nghe đơn giản: <strong>khách để lại liên hệ trên website, báo cho đúng người có trách nhiệm xử lý</strong>. Nhưng gửi thành công tới một dịch vụ chưa có nghĩa nhân viên đã nhìn thấy tin.</p><h2>Ba kênh, ba vai trò</h2><ul><li><p><strong>Vai trò phù hợp</strong> — Web Push: Nhắc người đã bật thông báo · Email: Bản lưu và kênh bổ sung · Zalo qua tích hợp chính thức: Khi đội dùng Zalo và luồng được nhà cung cấp hỗ trợ</p></li><li><p><strong>Điều kiện</strong> — Web Push: HTTPS, service worker, quyền thông báo, thiết bị tương thích · Email: Địa chỉ nhận và cấu hình gửi · Zalo qua tích hợp chính thức: Sản phẩm API, tài khoản, quyền và mẫu phù hợp</p></li><li><p><strong>Giao nhận</strong> — Web Push: Có thể trễ hoặc bị hệ điều hành chặn · Email: Có thể trễ, vào spam hoặc bị từ chối · Zalo qua tích hợp chính thức: Phụ thuộc chính sách, trạng thái tài khoản và dịch vụ</p></li><li><p><strong>Chi phí</strong> — Web Push: Không nhất thiết có phí từng tin; vẫn có chi phí vận hành · Email: Phụ thuộc hạ tầng hoặc gói gửi · Zalo qua tích hợp chính thức: Xác nhận báo giá và điều kiện tại thời điểm triển khai</p></li><li><p><strong>Dữ liệu lưu lại</strong> — Web Push: Cần lưu trong ứng dụng · Email: Thường có bản thư · Zalo qua tích hợp chính thức: Tuỳ sản phẩm tích hợp</p></li></ul><p>Không nên gọi Zalo là lựa chọn tệ nhất chỉ từ một bảng giá hay khung giờ được dẫn lại. Cũng cần phân biệt OA chat với dịch vụ gửi tin theo mẫu: chúng không phải cùng một API hay cùng điều kiện sử dụng.</p><h2>Nếu muốn dùng Zalo, xác nhận điều gì trước?</h2><p>Bản thảo cũ có các con số về giá, giờ gửi, cửa sổ hội thoại và vòng đời token nhưng không kèm nguồn chính sách gốc đủ để kiểm chứng. Bản này bỏ các con số đó, không dùng chúng làm cơ sở loại bỏ một kênh.</p><p>Trước khi thiết kế tích hợp, đối chiếu tại <a href=\\"https://developers.zalo.me/\\" rel=\\"nofollow\\">Zalo Developers</a> và xác nhận với nhà cung cấp: luồng báo tin cho nhân viên có được hỗ trợ không, người nhận cần đồng ý thế nào, có cần duyệt mẫu không, giới hạn gửi, chi phí và quy trình cấp lại quyền. Đừng xây quanh một cách lách mục đích API.</p><p>Token cần lưu an toàn, xử lý hết hạn và mất quyền, chống chạy làm mới đồng thời nếu cơ chế token yêu cầu, và có cảnh báo khi kết nối hỏng. Chi tiết phải theo tài liệu của đúng sản phẩm API đang dùng.</p><h2>Web Push phù hợp khi đội thường làm việc trên trình duyệt</h2><p>Web Push cho phép nhận tin khi trang không ở phía trước, thậm chí không đang được tải. Nó cần một service worker đang hoạt động và người dùng cấp quyền. Việc hiện thông báo còn phụ thuộc trình duyệt, hệ điều hành, mạng, tiết kiệm pin và chế độ không làm phiền. Phải thử trên thiết bị thật; không hứa tức thì.</p><p>Không cần bắt buộc dùng một dịch vụ gửi tin thương mại, nhưng vẫn phụ thuộc push service của hệ sinh thái trình duyệt. Khoá VAPID chỉ là một phần; ứng dụng còn phải quản lý subscription, mã hoá payload và xử lý endpoint hết hạn.</p><h2>Bốn quyết định thiết kế</h2><h3>1. Payload mỏng, dữ liệu lấy sau đăng nhập</h3><p>Nội dung có thể hiện trên màn hình khoá. Chỉ gửi loại sự kiện và định danh khó đoán, không gửi lời khách hay thông tin cá nhân. Khi bấm, ứng dụng kiểm tra phiên và quyền trước khi lấy chi tiết. Mã định danh không thay thế phân quyền; cũng không để khoá hay token truy cập trong liên kết thông báo.</p><h3>2. Gộp sự kiện để tránh gây phiền</h3><p>Khách gõ năm dòng không nhất thiết cần năm tiếng chuông. Có thể chỉ báo tin đầu cuộc hội thoại hoặc gộp trong một cửa sổ ngắn. Đăng ký nhận tin lặp lại không được coi là một khách mới chỉ vì endpoint lại trả thành công.</p><h3>3. Đúng người, có người thay thế</h3><p>Định tuyến theo người phụ trách và quyền xem dữ liệu. Không báo cho người không mở được màn hình đích. Nếu quá hạn chưa nhận xử lý, chuyển cho người trực dự phòng. Ghi trạng thái riêng: sự kiện đã lưu, đã gửi tới dịch vụ, đã được nhận xử lý; không gộp chúng thành một trạng thái &#34;đã giao&#34;.</p><h3>4. Tôn trọng giờ trực</h3><p>Chỉ dùng thông báo bám màn hình nếu thiết bị hỗ trợ và tình huống cần thiết. Có lịch trực, giờ yên lặng và mức ưu tiên. Khách gửi lúc 23 giờ không mặc định là lý do đánh thức cả đội.</p><h2>Service worker cũ có thể làm mất thông báo</h2><p>Bản thảo kể lại một sự cố worker cũ bỏ qua các loại tin mới:</p><pre><code>if (data.kind &amp;&amp; data.kind !== &#34;visitor_waiting&#34;) return;</code></pre><p>CDN có thể giữ bản cũ; vòng đời cài đặt và kích hoạt worker cũng có thể trì hoãn bản mới. Kiểm tra cả hai thay vì chỉ xoá cache trình duyệt.</p><p>Với URL worker không đổi, dùng chính sách tái xác thực phù hợp như <code>Cache-Control: no-cache</code>, kiểm tra CDN có ghi đè không và có worker mới đang chờ kích hoạt không. <code>no-cache</code> không có nghĩa cấm lưu. Thêm số phiên bản để biết thiết bị đang chạy bản nào, rồi thử toàn bộ luồng trên thiết bị thật.</p><h2>Cách chọn cho nhóm nhỏ</h2><p>Bắt đầu bằng <strong>Web Push để nhắc và email để lưu</strong>, nếu đội đã dùng màn hình quản trị thường xuyên. Thiết kế hàng đợi, retry có giới hạn, chống gửi trùng và cảnh báo thất bại. Trong ứng dụng luôn có danh sách việc chưa xử lý để không phụ thuộc hoàn toàn vào tiếng chuông.</p><p>Nếu đội chủ yếu dùng Zalo, đánh giá tích hợp chính thức sau khi xác nhận luồng được hỗ trợ và chính sách hiện hành. Tiêu chí cuối cùng là có người nhận việc trong thời hạn đã thống nhất, không phải kênh nào quen thuộc nhất.</p><hr><p><em>Sự cố worker được thuật lại từ bản thảo Zukatek tháng 10/2026, chưa có log gốc để xác minh độc lập. Bài này không xác nhận giá hay chính sách Zalo.</em></p><p>Nguồn đối chiếu: <a href=\\"https://developer.mozilla.org/en-US/docs/Web/API/Push_API\\" rel=\\"nofollow\\">MDN — Push API</a>, <a href=\\"https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control\\" rel=\\"nofollow\\">MDN — Cache-Control</a>.</p><p><em>Ảnh bìa là minh hoạ tạo bằng AI, không phải ảnh chụp hệ thống thật.</em></p>", "category_id": "527817a9-ade5-46d4-b64d-37d4bff2c875", "published_at": "2026-10-18T12:56:36.4235624+07:00", "featured_path": "cms/articles/5eb8c4fb-5989-51c1-b18a-635d80045a77/featured-706ec641-d316-5398-8104-b90cfa9605aa.webp"}', '2026-10-18 12:44:14.814549+07', '2026-10-18 12:56:36.435812+07')
