INSERT INTO published_docs (entity, locale, slug, entity_id, is_current, search_text, body, published_at, written_at)
VALUES ('article', 'vi', 'toi-uu-server-do-truoc-sua-sau', '08b8b7ff-a37f-5dd7-b22e-ac903e29b901', true, 'Tối ưu server: đo trước, sửa sau — và những con số thật từ một VPS 3GB Chúng tôi đo toàn bộ đường đi của một yêu cầu, từ trình duyệt tới cơ sở dữ liệu. Máy chủ trả lời trong 3 mili giây, người dùng chờ 130. Bài này chỉ ra cách tách thời gian xử lý, đường truyền và tải tài nguyên.', E'{"seo": {"title": "Tối ưu server đúng chỗ: đo trước, sửa sau (số liệu thật)", "noindex": false, "keywords": "tối ưu server, hiệu năng web, TTFB, nén gzip, tối ưu hình ảnh, VPS", "nofollow": false, "og_title": "", "description": "Hướng dẫn đo hiệu năng web từ đầu tới cuối, với số liệu thật từ một VPS 4 nhân 3GB: đâu là nút thắt thật, đâu là chỗ tiêu tiền vô ích.", "canonical_url": "", "og_description": ""}, "slug": "toi-uu-server-do-truoc-sua-sau", "title": "Tối ưu server: đo trước, sửa sau — và những con số thật từ một VPS 3GB", "excerpt": "Chúng tôi đo toàn bộ đường đi của một yêu cầu, từ trình duyệt tới cơ sở dữ liệu. Máy chủ trả lời trong 3 mili giây, người dùng chờ 130. Bài này chỉ ra cách tách thời gian xử lý, đường truyền và tải tài nguyên.", "og_path": null, "tag_ids": [], "body_html": "<p>Câu hỏi &#34;làm sao cho web nhanh hơn&#34; gần như luôn được trả lời sai, vì nó được trả lời <strong>trước khi đo</strong>. Người ta nâng CPU, thêm RAM, đổi sang máy chủ mạnh hơn — rồi phát hiện trang vẫn chậm y như cũ.</p><p>Bài này kể lại đúng những gì chúng tôi đo được trên hệ thống của mình, theo đúng thứ tự đã đo, kèm con số.</p><h2>Hệ thống được đo</h2><p><em>Bản thảo gốc ghi các số liệu dưới đây vào ngày 18/10/2026. Chưa có log gốc trong thư mục để xác minh độc lập. Đây là quan sát ở một cấu hình, không phải benchmark đại diện; cần đo lại dưới tải thực tế.</em></p><ul><li><p>Một VPS: <strong>4 nhân, 2.9 GB RAM</strong>, đặt tại Việt Nam</p></li><li><p>Trên đó: trang web công khai dựng phía máy chủ (Node), màn hình quản trị (tệp tĩnh), API (Go), PostgreSQL 16</p></li><li><p>Và một ứng dụng của một công ty khác chạy chung máy</p></li></ul><h2>Bước 1: đo từ trong ra ngoài, không đo từ ngoài vào</h2><p>Sai lầm thường gặp là mở trang web, thấy chậm, rồi kết luận &#34;server yếu&#34;. Phép đo đó gộp chung bốn thứ: máy chủ, đường truyền, CDN, và cân nặng trang. Phải tách ra.</p><p>Đo <strong>ngay trên máy chủ</strong>, qua loopback — loại bỏ hoàn toàn mạng:</p><pre><code>SSR nội bộ:   3.1 ms   3.3 ms   2.9 ms\\nAPI nội bộ /members:       5.1 ms\\nAPI nội bộ /menus:         4.3 ms\\nAPI nội bộ /settings:      3.7 ms\\nTải trung bình:            0.06\\nRAM còn trống:             1.9 GB</code></pre><p>Ở các mẫu này, <strong>chưa thấy dấu hiệu máy chủ là nút thắt</strong>. Load average 0.06 không có nghĩa CPU rảnh 99%. Cần thêm CPU, I/O, bộ nhớ, số yêu cầu đồng thời và p95/p99 dưới tải trước khi kết luận về năng lực máy.</p><p>Nếu bạn chỉ làm một việc trong bài này, hãy làm phép đo trên. Nó mất ba phút và nó quyết định toàn bộ phần còn lại.</p><h2>Bước 2: đo từ ngoài, cùng một thứ</h2><pre><code>Từ máy người dùng (Việt Nam), nối thẳng:\\n  bắt tay TLS:   0.06–0.08 s\\n  TTFB:          0.08–0.10 s\\n  tổng:          0.10–0.13 s</code></pre><p>Không nên lấy tổng thời gian tải bên ngoài trừ thời gian phản hồi nội bộ rồi gọi phần dư là độ trễ mạng. Hãy đo cùng URL, cùng nội dung và tách DNS, TCP, TLS, TTFB, tải body; đo nhiều lần với cache và kết nối được kiểm soát.</p><h2>Bước 3: cân nặng trang — nơi tiền thật sự nằm</h2><p>Đây là chỗ chúng tôi tìm ra vấn đề lớn nhất, và nó không liên quan gì tới máy chủ:</p><ul><li><p><code>entry-client.js</code> — Gốc: 482 KB · Sau nén: 152 KB</p></li><li><p><code>esm.js</code> — Gốc: 318 KB · Sau nén: —</p></li><li><p><strong>CSS</strong> — Gốc: 135 KB · Sau nén: 30 KB</p></li><li><p><strong>Ảnh đại diện một người</strong> — Gốc: <strong>697 KB</strong> · Sau nén: <strong>516 KB (WebP)</strong></p></li><li><p><code>logo.png</code> — Gốc: 140 KB · Sau nén: —</p></li><li><p><code>favicon.png</code> — Gốc: 49 KB · Sau nén: —</p></li><li><p><strong>18 tệp phông chữ</strong> — Gốc: 290 KB · Sau nén: —</p></li></ul><p><strong>Ảnh chân dung này nặng hơn tệp </strong><code>entry-client.js</code><strong> sau nén.</strong> Chưa đủ dữ liệu để kết luận về tổng JavaScript của trang. 516 KB cho một khung hiển thị rộng khoảng 320 điểm ảnh.</p><p>Tệ hơn: khi chúng tôi thử yêu cầu bản nhỏ bằng tham số <code>?w=320</code>, máy chủ <strong>bỏ qua tham số</strong> và vẫn trả ảnh gốc. Nghĩa là có sẵn cơ chế thay đổi kích thước nhưng nó không hoạt động — loại lỗi chỉ lộ ra khi đo, vì trang vẫn hiển thị đúng.</p><h3>Bài học</h3><p>Thứ tự tối ưu theo mức hiệu quả trên công sức, với một trang web điển hình:</p><ol><li><p><strong>Ảnh</strong> — gần như luôn là thứ nặng nhất, và gần như luôn dễ sửa nhất</p></li><li><p><strong>Nén</strong> — kiểm tra xem máy chủ có thật sự nén không, đừng tin cấu hình</p></li><li><p><strong>Cache ở biên</strong> cho tệp tĩnh</p></li><li><p><strong>Mã JavaScript</strong> — khó và lâu nhất, để sau cùng</p></li><li><p><strong>Phần cứng</strong> — khi số đo cho thấy CPU, RAM hoặc I/O là giới hạn</p></li></ol><h2>Bước 4: kiểm tra nén có thật sự chạy không</h2><p>Cấu hình <code>gzip on;</code> trong nginx <strong>không có nghĩa là nó đang nén thứ bạn nghĩ</strong>. <code>text/html</code> luôn được module gzip hỗ trợ; muốn nén CSS và JavaScript, cần khai báo MIME type phù hợp trong <code>gzip_types</code>.</p><p>Đừng đọc file cấu hình rồi kết luận. Hãy đo.</p><p>Cách kiểm tra đúng là hỏi như một trình duyệt thật và nhìn số byte tải về:</p><pre><code>curl -s -o /dev/null --compressed -w &#39;%{size_download}&#39; https://ten-mien/</code></pre><p>Đối chiếu thêm header <code>Content-Encoding</code> và cùng một response không nén. Số byte nhỏ hơn chưa tự chứng minh thuật toán nén nào được dùng. Bản thảo ghi HTML khoảng 91 KB và body truyền về khoảng <strong>21 KB</strong>; chưa có header gốc để xác nhận zstd.</p><h2>Bước 5: cẩn thận với phép đo tự lừa mình</h2><p>Đây là sai lầm <strong>tôi đã mắc</strong> trong chính lần đo này, và nó đáng kể lại.</p><p>Lần đầu tôi đo tốc độ qua CDN bằng cách chạy <code>curl</code> <strong>từ chính máy chủ</strong>. Kết quả: 348–838 mili giây. Tôi suýt kết luận CDN làm chậm gấp tám lần.</p><p>Nhưng phép đo đó sai về bản chất: yêu cầu đi từ máy chủ → ra Internet → tới CDN → quay ngược lại chính máy chủ đó. Nó đo một đường vòng mà <strong>không người dùng nào đi</strong>.</p><p>Đo lại từ một máy người dùng thật ở Việt Nam, bản thảo ghi 0.31–0.49 giây. Tuy nhiên hai đường khi đó đo hai ứng dụng khác nhau; chưa thể dùng chênh lệch này để định lượng chi phí của CDN.</p><p><strong>Nguyên tắc:</strong> đo ở đúng vị trí người dùng đứng. Một phép đo tiện tay thường là một phép đo sai.</p><h2>Bước 6: những thứ không nằm trong tầm kiểm soát</h2><p>Có những nút thắt bạn đo ra nhưng không sửa được, và biết sớm thì đỡ mất thời gian. Chúng tôi gặp một cái rất lạ: <strong>kết nối cổng 80 từ một số mạng quốc tế không tới được máy.</strong></p><p>Triệu chứng là chứng chỉ SSL không cấp được, báo &#34;connection reset&#34;. Mọi dấu hiệu đều chỉ về phía cấu hình máy chủ. Nhưng bắt gói tin cho thấy sự thật:</p><pre><code>Từ mạng nước ngoài gọi vào cổng 80:  KHÔNG một gói SYN nào tới máy\\nTừ mạng trong nước gọi vào cổng 80:  SYN tới, máy trả SYN-ACK</code></pre><p>Gói tin bị chặn <strong>trước khi tới máy</strong>. Không cấu hình nào trên máy sửa được điều đó.</p><p>Bài học ở đây không phải về cổng 80. Là về <strong>phép đối chứng</strong>: nếu tôi chỉ chạy phép đo từ nước ngoài và thấy không có gói nào, tôi có thể kết luận bộ lọc gói tin của mình hỏng. Chính phép đo đối chứng từ trong nước — thấy gói tin tới bình thường — giúp khoanh vùng vấn đề có thể nằm ở đường đi hoặc bộ lọc phía trước máy. Chưa đủ bằng chứng để khẳng định nhà cung cấp chủ động chặn cổng.</p><p><strong>Mọi phép đo cho kết quả &#34;không có gì&#34; đều cần một phép đối chứng cho kết quả &#34;có&#34;.</strong> Nếu không, bạn không phân biệt được &#34;không có gì xảy ra&#34; với &#34;dụng cụ đo hỏng&#34;.</p><h2>Danh sách kiểm tra</h2><p>Chạy theo thứ tự này, dừng lại ngay khi tìm ra nút thắt:</p><ol><li><p>Đo trên loopback — máy chủ có chậm không? <em>(thường là không)</em></p></li><li><p>Đo từ máy người dùng thật — chênh lệch nằm ở đâu?</p></li><li><p>Liệt kê tài sản tĩnh theo kích thước giảm dần — ảnh có nằm đầu không?</p></li><li><p>Kiểm tra nén bằng <code>--compressed</code>, nhìn số byte</p></li><li><p>Kiểm tra cache ở biên: header <code>cf-cache-status</code> hoặc tương đương</p></li><li><p>Chỉ khi cả năm bước trên đều sạch, mới nghĩ tới phần cứng</p></li></ol><hr><p><em>Số liệu được giữ từ bản thảo về Zukatek, tháng 10/2026; chưa xác minh độc lập trong lần rà soát này. Con số của bạn sẽ khác. Hãy giữ phương pháp và lưu log của từng lần đo.</em></p><p>Nguồn đối chiếu: <a href=\\"https://nginx.org/en/docs/http/ngx_http_gzip_module.html\\" rel=\\"nofollow\\">nginx gzip module</a>.</p><p><em>Ảnh bìa là minh hoạ tạo bằng AI, không phải ảnh chụp hệ thống thật.</em></p>", "category_id": "527817a9-ade5-46d4-b64d-37d4bff2c875", "published_at": "2026-10-18T12:57:18.1774292+07:00", "featured_path": "cms/articles/08b8b7ff-a37f-5dd7-b22e-ac903e29b901/featured-c6d8e5e6-6ba7-530e-9521-739be761b6e5.webp"}', '2026-10-18 12:57:18.177854+07', '2026-10-18 12:57:18.185689+07')
